from typing import Sequence

def tropical_hash(message: Sequence[float], key: Sequence[float]) -> float:
    if not message or len(message) != len(key):
        raise ValueError("nonempty vectors of equal length required")
    return min(x + a for x, a in zip(message, key))

def canonical_preimage(key: Sequence[float], target: float) -> list[float]:
    if not key:
        raise ValueError("key must be nonempty")
    return [target - a for a in key]

key = [7.0, -2.0, 11.0, 4.0]
target = 23.0
message = canonical_preimage(key, target)
print(message, tropical_hash(message, key))
assert tropical_hash(message, key) == target

def gap(v: tuple[float, float], w: tuple[float, float], t: float) -> float:
    if not 0 <= t <= 1: raise ValueError("t must lie in [0,1]")
    lhs = min((1-t)*v[0]+t*w[0], (1-t)*v[1]+t*w[1])
    rhs = (1-t)*min(v) + t*min(w)
    return lhs-rhs

for t in [i/10 for i in range(11)]:
    print(t, gap((0,5), (7,1), t))
    assert gap((0,5), (7,1), t) >= -1e-12

